final class Orion_AI_Diagnostics_Service{
 private Orion_Intent_Classifier $classifier;private Orion_Knowledge_Base $knowledge;private Orion_Semantic_Product_Planner $planner;public function __construct(Orion_Intent_Classifier $classifier,Orion_Knowledge_Base $knowledge,Orion_Semantic_Product_Planner $planner){$this->classifier=$classifier;$this->knowledge=$knowledge;$this->planner=$planner;}
 public function run(string $prompt,array $settings):array{$started=microtime(true);$classification=$this->classifier->classify($prompt,array(),array(),$settings);$report=array('prompt'=>$prompt,'provider'=>Orion_AI_Settings::provider($settings),'model'=>Orion_AI_Settings::stage_model($settings,'routing',Orion_AI_Settings::provider($settings)),'classification'=>$classification,'knowledge'=>array(),'products'=>array(),'outcome'=>'classified');if(!empty($classification['needs_clarification'])){$report['outcome']='clarification_required';return$this->finish($report,$started);}$intent=$classification['intent']??'manager_follow_up';if('store_policy'===$intent){$query=$classification['policy_query']?:$prompt;$docs=$this->knowledge->relevant($query,5);$report['knowledge']=array('query'=>$query,'results'=>array_map(static fn($d)=>array('title'=>$d['title'],'source_url'=>$d['source_url'],'excerpt'=>mb_substr($d['markdown'],0,300)),$docs));if(!$docs)$report['outcome']='knowledge_no_results';else{$provider=Orion_AI_Provider_Factory::create($settings);$result=$provider->chat(array(array('role'=>'system','content'=>'Determine whether the documents explicitly answer the store-policy question. Return JSON only: {"supported":true,"reason":"..."}. Never infer delivery areas, pallet service, prices, dates or guarantees.'),array('role'=>'user','content'=>wp_json_encode(array('question'=>$prompt,'documents'=>$docs)))));$data=!empty($result['ok'])?$this->decode((string)($result['message']['content']??'')):null;$report['knowledge']['validation']=array('provider_ok'=>!empty($result['ok']),'supported'=>!empty($data['supported']),'reason'=>sanitize_text_field((string)($data['reason']??($result['error']??''))),'usage'=>$result['usage']??array());$report['outcome']=!empty($data['supported'])?'knowledge_supported':'knowledge_not_supported';}}elseif(in_array($intent,array('project_recommendation','product_search'),true)){$kit=$this->planner->recommend($classification,$classification['state_patch']??array(),$settings);$report['products']=array('selected'=>array_map(static fn($p)=>array('id'=>$p['id'],'name'=>$p['name'],'role'=>$p['kit_role']??'','roles'=>$p['kit_roles']??array($p['kit_role']??'')),$kit['products']),'missing_roles'=>$kit['missing_roles'],'conditional_roles'=>$kit['conditional_roles']??array(),'plan'=>array_map(static fn($g)=>array('role'=>$g['role'],'required'=>$g['required'],'candidates'=>array_map(static fn($p)=>array('id'=>$p['id'],'name'=>$p['name'],'categories'=>$p['categories']),$g['candidates'])),$kit['plan']),'diagnostic'=>$kit['diagnostic']??array());$report['outcome']=$kit['products']?'verified_products_found':'required_products_missing';}elseif('manager_follow_up'===$intent)$report['outcome']='classifier_requested_handoff';return$this->finish($report,$started);}
 private function finish(array $report,float $started):array{$report['duration_ms']=(int)round((microtime(true)-$started)*1000);return$report;}private function decode(string $text):?array{$text=trim(preg_replace('/^```(?:json)?\s*|\s*```$/i','',trim($text)));$data=json_decode($text,true);if(is_array($data))return$data;if(preg_match('/\{[\s\S]*\}/',$text,$m)){$data=json_decode($m[0],true);return is_array($data)?$data:null;}return null;}
}
